import { IOptionalXmlNode, IXmlNode, IXmlNodeAttributes } from '../types';

function getNode<T extends IXmlNode>(node: Node, verbose: boolean = false): T {
    const attributes: { [key: string]: string } = {};
    const attributeCount = (node as Element).attributes.length;

    for (let index = 0; index < attributeCount; index++) {
        const attribute = (node as Element).attributes[index];
        if (attribute.nodeValue !== null) {
            attributes[attribute.nodeName] = attribute.nodeValue;
        }
    }

    const childNodes: { [key: string]: IXmlNode[] } = {};
    const childCount = node.childNodes.length;

    for (let index = 0; index < childCount; index++) {
        const childNode: ChildNode = node.childNodes[index];
        if (childNode.nodeName === 'payload' && childNode.firstChild instanceof CDATASection) {
            attributes.cdataPayload = childNode.firstChild.data;
            continue;
        }
        if (childNode.nodeName === '#text') {
            if (verbose) {
                console.warn(`node.childNodes[${index}] with nodeName of #text invalid`, childNode, node);
            }
            continue;
        }
        if (childNodes[childNode.nodeName]) {
            childNodes[childNode.nodeName].push(getNode(childNode, verbose));
        } else {
            childNodes[childNode.nodeName] = [getNode(childNode, verbose)];
        }
    }

    const result = {
        attributes,
        childNodes,
        name: node.nodeName
    };

    return result as T;
}

function parseXmlNode(xml: string): Node | null {
    let dom: any;

    if ((window as any).DOMParser) {
        try {
            dom = new DOMParser().parseFromString(xml.replace(/&(?!(quot;|lt;|gt;))/, '&amp;'), 'text/xml');
        } catch (e) {
            dom = null;
        }
    } else if ((window as any).ActiveXObject) {
        try {
            dom = new window.ActiveXObject('Microsoft.XMLDOM');
            dom.async = false;
            if (!dom.loadXML(xml)) {
                throw new Error(`Failed to load XML data: ${dom.parseError.reason}`);
            }
        } catch (e) {
            dom = null;
        }
    }

    return dom;
}

export function getFirstChildNode<T extends IXmlNode>(xml: string, verbose: boolean = false): T | null {
    const data = parseXmlNode(xml);

    if (!data) {
        return null;
    }

    const child = data.firstChild;
    return child ? getNode<T>(child, verbose) : null;
}

function xmlNodeAttributesToString(attributes?: IXmlNodeAttributes) {
    return attributes ? Object.entries(attributes).map(([key, value], index) => (index === 0 ? ' ' : '') + `${key}="${value}"`).join(' ') : '';
}

export function xmlNodeToString(node: IOptionalXmlNode): string {
    const nodeStart = `<${node.name}`;
    const nodeAttributes = xmlNodeAttributesToString(node.attributes);

    if (!node.childNodes || Object.keys(node.childNodes).length === 0) {
        return `${nodeStart}${nodeAttributes}/>`;
    }

    const childNodesString = Object.values(node.childNodes).map((nodes) => {
        return nodes.map((node) => {
            return xmlNodeToString(node);
        }).join('');
    }).join('');
    const nodeEnd = `</${node.name}>`;
    return `${nodeStart}${nodeAttributes}>${childNodesString}${nodeEnd}`;
}